export async function handleWebhook(store, event) {
  if (!event || typeof event !== "object" ||
      typeof event.id !== "string" || event.id.length === 0 ||
      typeof event.chargeId !== "string" || event.chargeId.length === 0 ||
      event.type !== "payment.succeeded") {
    throw new Error("INVALID_EVENT");
  }

  if (store.events.has(event.id)) {
    return { accepted: false };
  }

  store.events.add(event.id);
  if (!store.receipts.some((receipt) => receipt.chargeId === event.chargeId)) {
    store.receipts.push(event);
  }
  return { accepted: true };
}
